def check_exit(results, open_defects):
    failed = []
    executed = [r for r in results if r != 'not run']
    if not results or len(executed) / len(results) < 0.95:
        failed.append('execution')
    if not executed or sum(r == 'pass' for r in executed) / len(executed) < 0.90:
        failed.append('pass_rate')
    if any(s in ('critical', 'high') for s in open_defects):
        failed.append('defects')
    return failed
